-- V38: amplia el banco de trivia (F4) a 6 categorias y ~150 preguntas nuevas (ES+EN).
-- Reparto: FITNESS y NUTRICION suman 25 mas cada una (a las 25 de V2); ENTRENAMIENTO, ANATOMIA,
-- SUPLEMENTACION y CULTURA_FITNESS entran nuevas con 25 cada una -> ~200 preguntas en total, 6 categorias.
ALTER TABLE trivia_preguntas DROP CHECK chk_trivia_categoria;
ALTER TABLE trivia_preguntas ADD CONSTRAINT chk_trivia_categoria
    CHECK (categoria IN ('FITNESS','NUTRICION','ENTRENAMIENTO','ANATOMIA','SUPLEMENTACION','CULTURA_FITNESS'));

INSERT INTO trivia_preguntas
    (categoria, dificultad, pregunta_es, pregunta_en,
     opcion_a_es, opcion_a_en, opcion_b_es, opcion_b_en,
     opcion_c_es, opcion_c_en, opcion_d_es, opcion_d_en, correcta) VALUES
('ENTRENAMIENTO', 'FACIL', '¿Qué rango de repeticiones se asocia clásicamente con el desarrollo de la fuerza máxima?', 'Which rep range is classically associated with developing maximal strength?', '1-5 repeticiones', '1-5 reps', '8-12 repeticiones', '8-12 reps', '15-20 repeticiones', '15-20 reps', '25-30 repeticiones', '25-30 reps', 'A'),
('ENTRENAMIENTO', 'FACIL', '¿Qué significa el acrónimo RPE en el contexto del entrenamiento?', 'What does the acronym RPE stand for in training?', 'Repeticiones Por Ejercicio', 'Repetitions Per Exercise', 'Percepción del Esfuerzo (Rate of Perceived Exertion)', 'Rate of Perceived Exertion', 'Ritmo de Pulso en Ejercicio', 'Exercise Pulse Rate', 'Resistencia Progresiva del Entrenamiento', 'Progressive Resistance Exercise', 'B'),
('ENTRENAMIENTO', 'FACIL', '¿Qué rango de repeticiones se considera clásicamente óptimo para la hipertrofia muscular?', 'Which rep range is classically considered optimal for muscle hypertrophy?', '1-3 repeticiones', '1-3 reps', '4-6 repeticiones', '4-6 reps', '6-12 repeticiones', '6-12 reps', '20-25 repeticiones', '20-25 reps', 'C'),
('ENTRENAMIENTO', 'FACIL', '¿Cómo se llama la contracción muscular en la que el músculo se acorta mientras genera tensión?', 'What is the muscle contraction called when the muscle shortens while generating tension?', 'Isométrica', 'Isometric', 'Excéntrica', 'Eccentric', 'Isocinética', 'Isokinetic', 'Concéntrica', 'Concentric', 'D'),
('ENTRENAMIENTO', 'FACIL', '¿Cómo se llama la contracción en la que el músculo se alarga mientras soporta tensión, como al bajar un peso de forma controlada?', 'What is the contraction called when the muscle lengthens under tension, such as lowering a weight with control?', 'Excéntrica', 'Eccentric', 'Concéntrica', 'Concentric', 'Isométrica', 'Isometric', 'Pliométrica', 'Plyometric', 'A'),
('ENTRENAMIENTO', 'FACIL', '¿Qué principio del entrenamiento consiste en aumentar gradualmente la carga, el volumen o la dificultad de los ejercicios con el tiempo?', 'Which training principle involves gradually increasing load, volume, or difficulty over time?', 'Especificidad', 'Specificity', 'Variación', 'Variation', 'Sobrecarga progresiva', 'Progressive overload', 'Individualización', 'Individualization', 'C'),
('ENTRENAMIENTO', 'FACIL', '¿Cuánto descanso entre series se recomienda habitualmente cuando el objetivo es la fuerza máxima con cargas pesadas?', 'How much rest between sets is typically recommended when the goal is maximal strength with heavy loads?', '15-30 segundos', '15-30 seconds', '3-5 minutos', '3-5 minutes', '45 segundos', '45 seconds', '90 segundos', '90 seconds', 'B'),
('ENTRENAMIENTO', 'FACIL', '¿Cómo se conoce al tipo de entrenamiento cardiovascular que alterna intervalos cortos de esfuerzo máximo con periodos de recuperación?', 'What is the cardiovascular training method called that alternates short bursts of maximal effort with recovery periods?', 'LISS (Low Intensity Steady State)', 'LISS', 'Entrenamiento continuo', 'Continuous training', 'Fartlek sueco', 'Swedish fartlek', 'HIIT (entrenamiento interválico de alta intensidad)', 'HIIT (High Intensity Interval Training)', 'D'),
('ENTRENAMIENTO', 'MEDIA', '¿Cómo se denomina la organización planificada del entrenamiento en ciclos con distintos objetivos de volumen e intensidad a lo largo del tiempo?', 'What is the planned organization of training into cycles with varying volume and intensity goals over time called?', 'Periodización', 'Periodization', 'Sobrecarga progresiva', 'Progressive overload', 'Especificidad', 'Specificity', 'Densidad de entrenamiento', 'Training density', 'A'),
('ENTRENAMIENTO', 'MEDIA', 'En periodización, ¿cuál es el orden correcto de mayor a menor duración de los ciclos de entrenamiento?', 'In periodization, what is the correct order of training cycles from longest to shortest duration?', 'Mesociclo, macrociclo, microciclo', 'Mesocycle, macrocycle, microcycle', 'Macrociclo, mesociclo, microciclo', 'Macrocycle, mesocycle, microcycle', 'Microciclo, mesociclo, macrociclo', 'Microcycle, mesocycle, macrocycle', 'Macrociclo, microciclo, mesociclo', 'Macrocycle, microcycle, mesocycle', 'B'),
('ENTRENAMIENTO', 'MEDIA', 'En la escala RPE (0-10), ¿qué representa un valor de RPE 10?', 'On the RPE scale (0-10), what does a value of RPE 10 represent?', 'Esfuerzo muy ligero, calentamiento', 'Very light effort, warm-up', 'Aún quedan 3-4 repeticiones en reserva', '3-4 reps still in reserve', 'Fallo muscular, no queda ninguna repetición en reserva', 'Muscular failure, no reps left in reserve', 'Esfuerzo moderado con 5 repeticiones en reserva', 'Moderate effort with 5 reps in reserve', 'C'),
('ENTRENAMIENTO', 'MEDIA', 'Si un atleta reporta un RIR (Repeticiones en Reserva) de 2 tras una serie, ¿a qué valor aproximado de RPE equivale?', 'If an athlete reports an RIR (Reps in Reserve) of 2 after a set, what approximate RPE value does that equal?', 'RPE 5', 'RPE 5', 'RPE 10', 'RPE 10', 'RPE 6', 'RPE 6', 'RPE 8', 'RPE 8', 'D'),
('ENTRENAMIENTO', 'MEDIA', '¿Qué tipo de contracción muscular genera tensión sin que se produzca cambio en la longitud del músculo, como en una plancha (plank)?', 'Which type of muscle contraction generates tension without a change in muscle length, as in a plank hold?', 'Isométrica', 'Isometric', 'Concéntrica', 'Concentric', 'Excéntrica', 'Eccentric', 'Auxotónica', 'Auxotonic', 'A'),
('ENTRENAMIENTO', 'MEDIA', '¿Con qué objetivo de entrenamiento se asocian con más frecuencia los descansos cortos, de 30 a 60 segundos, entre series?', 'Which training goal is most often associated with short rest periods of 30 to 60 seconds between sets?', 'Fuerza máxima', 'Maximal strength', 'Hipertrofia y resistencia muscular', 'Hypertrophy and muscular endurance', 'Potencia explosiva', 'Explosive power', 'Velocidad máxima', 'Maximal speed', 'B'),
('ENTRENAMIENTO', 'MEDIA', '¿Qué nombre recibe el principio que establece que el cuerpo se adapta específicamente al tipo de exigencia impuesta (SAID: Specific Adaptation to Imposed Demands)?', 'What is the principle called that states the body adapts specifically to the type of demand imposed (SAID: Specific Adaptation to Imposed Demands)?', 'Sobrecarga progresiva', 'Progressive overload', 'Reversibilidad', 'Reversibility', 'Especificidad', 'Specificity', 'Supercompensación', 'Supercompensation', 'C'),
('ENTRENAMIENTO', 'MEDIA', '¿Cómo se llama la semana o periodo de entrenamiento con volumen e intensidad reducidos, planificado para favorecer la recuperación?', 'What is a training week or period with reduced volume and intensity, planned to favor recovery, called?', 'Microciclo de choque', 'Shock microcycle', 'Sobreentrenamiento', 'Overtraining', 'Pico de forma (peaking)', 'Peaking', 'Semana de descarga (deload)', 'Deload week', 'D'),
('ENTRENAMIENTO', 'MEDIA', '¿Cómo se denomina la relación entre el trabajo realizado y el tiempo total empleado (incluyendo descansos) en una sesión de entrenamiento?', 'What is the relationship between work performed and total time spent (including rests) in a training session called?', 'Densidad de entrenamiento', 'Training density', 'Volumen de entrenamiento', 'Training volume', 'Intensidad relativa', 'Relative intensity', 'Frecuencia de entrenamiento', 'Training frequency', 'A'),
('ENTRENAMIENTO', 'DIFICIL', 'En la notación de tempo de un ejercicio (por ejemplo, 4-1-2-0), ¿qué representa habitualmente el primer número?', 'In exercise tempo notation (e.g., 4-1-2-0), what does the first number typically represent?', 'La fase concéntrica', 'The concentric phase', 'La fase excéntrica', 'The eccentric phase', 'La pausa en la posición final', 'The pause at the final position', 'El número de series', 'The number of sets', 'B'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se llama el modelo de periodización en el que el volumen y la intensidad varían de una sesión a otra dentro de la misma semana?', 'What is the periodization model called in which volume and intensity vary from one session to another within the same week?', 'Periodización lineal', 'Linear periodization', 'Periodización en bloques', 'Block periodization', 'Periodización ondulante diaria (DUP)', 'Daily undulating periodization (DUP)', 'Periodización conjugada', 'Conjugate periodization', 'C'),
('ENTRENAMIENTO', 'DIFICIL', 'Según la evidencia científica actual, ¿qué rango aproximado de series semanales por grupo muscular se asocia con ganancias óptimas de hipertrofia en la mayoría de personas entrenadas?', 'According to current scientific evidence, what approximate range of weekly sets per muscle group is associated with optimal hypertrophy gains in most trained individuals?', '1-3 series', '1-3 sets', '3-5 series', '3-5 sets', '40-50 series', '40-50 sets', '10-20 series', '10-20 sets', 'D'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se conoce el fenómeno por el cual combinar entrenamiento de resistencia cardiovascular y de fuerza en exceso puede atenuar las adaptaciones de fuerza e hipertrofia?', 'What is the phenomenon called in which combining excessive cardiovascular endurance training with strength training can blunt strength and hypertrophy adaptations?', 'Efecto de interferencia', 'Interference effect', 'Efecto de repetición', 'Repetition effect', 'Efecto de meseta', 'Plateau effect', 'Efecto de potenciación', 'Potentiation effect', 'A'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se denomina el punto en una serie en el que se pierde la técnica correcta del ejercicio antes de alcanzar el verdadero fallo muscular concéntrico?', 'What is the point in a set called where correct exercise technique breaks down before reaching true concentric muscular failure?', 'Fallo muscular absoluto', 'Absolute muscular failure', 'Fallo técnico', 'Technical failure', 'Fallo excéntrico', 'Eccentric failure', 'Punto de supercompensación', 'Supercompensation point', 'B'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se llama la capacidad de generar la máxima fuerza posible en el menor tiempo posible, clave en la fuerza explosiva y distinta de la fuerza máxima?', 'What is the ability to generate the maximum possible force in the shortest possible time called, key to explosive strength and distinct from maximal strength?', 'Fuerza-resistencia', 'Strength endurance', 'Fuerza isométrica máxima', 'Maximal isometric strength', 'Tasa de desarrollo de fuerza (RFD)', 'Rate of force development (RFD)', 'Fuerza absoluta', 'Absolute strength', 'C'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se llama el fenómeno por el cual, tras un estímulo de entrenamiento y un periodo adecuado de recuperación, el rendimiento supera el nivel inicial previo al esfuerzo?', 'What is the phenomenon called in which, after a training stimulus and an adequate recovery period, performance rises above the initial level prior to the effort?', 'Fatiga acumulada', 'Accumulated fatigue', 'Sobreentrenamiento', 'Overtraining', 'Adaptación específica', 'Specific adaptation', 'Supercompensación', 'Supercompensation', 'D'),
('ENTRENAMIENTO', 'DIFICIL', '¿Cómo se conoce popularmente al entrenamiento cardiovascular realizado a una intensidad cercana al umbral aeróbico, sostenible durante largos periodos y asociado a mejoras mitocondriales?', 'What is cardiovascular training performed near the aerobic threshold, sustainable for long periods and associated with mitochondrial improvements, popularly known as?', 'Zona 2', 'Zone 2', 'Zona 5', 'Zone 5', 'Umbral anaeróbico', 'Anaerobic threshold', 'VO2 máx', 'VO2 max', 'A'),
('FITNESS', 'FACIL', '¿Qué grupo muscular trabaja principalmente la plancha (plank)?', 'Which muscle group does the plank primarily work?', 'Núcleo (abdominales y zona media)', 'Core (abdominals and midsection)', 'Cuádriceps', 'Quadriceps', 'Deltoides', 'Deltoids', 'Isquiotibiales', 'Hamstrings', 'A'),
('FITNESS', 'FACIL', '¿Qué grupo muscular es el protagonista principal en el peso muerto?', 'Which muscle group is the main protagonist in the deadlift?', 'Pectoral mayor', 'Pectoralis major', 'Cadena posterior: glúteos e isquiotibiales', 'Posterior chain: glutes and hamstrings', 'Deltoides anterior', 'Anterior deltoid', 'Bíceps braquial', 'Biceps brachii', 'B'),
('FITNESS', 'FACIL', '¿Qué músculo trabaja principalmente la dominada (pull-up)?', 'Which muscle does the pull-up primarily work?', 'Cuádriceps', 'Quadriceps', 'Tríceps braquial', 'Triceps brachii', 'Dorsal ancho', 'Latissimus dorsi', 'Trapecio superior', 'Upper trapezius', 'C'),
('FITNESS', 'FACIL', '¿Qué músculo es el objetivo principal del curl de bíceps?', 'Which muscle is the main target of the biceps curl?', 'Tríceps braquial', 'Triceps brachii', 'Deltoides anterior', 'Anterior deltoid', 'Antebrazo (flexores)', 'Forearm flexors', 'Bíceps braquial', 'Biceps brachii', 'D'),
('FITNESS', 'FACIL', '¿Qué músculos trabaja principalmente la elevación de talones (calf raise)?', 'Which muscles does the calf raise primarily work?', 'Gastrocnemio y sóleo', 'Gastrocnemius and soleus', 'Tibial anterior', 'Tibialis anterior', 'Cuádriceps', 'Quadriceps', 'Isquiotibiales', 'Hamstrings', 'A'),
('FITNESS', 'FACIL', '¿Cuál es el objetivo principal de calentar antes de entrenar?', 'What is the main goal of warming up before training?', 'Aumentar directamente la masa muscular', 'Directly increase muscle mass', 'Elevar la temperatura corporal y preparar articulaciones y músculos', 'Raise body temperature and prepare joints and muscles', 'Sustituir el entrenamiento de fuerza', 'Replace strength training', 'Quemar la mayoría de las calorías del día', 'Burn most of the day''s calories', 'B'),
('FITNESS', 'FACIL', '¿Qué significan las siglas HIIT?', 'What does the acronym HIIT stand for?', 'Entrenamiento de resistencia de baja intensidad', 'Low-Intensity endurance Training', 'Entrenamiento isométrico de impacto total', 'Total-impact isometric training', 'Entrenamiento de intervalos de alta intensidad', 'High-Intensity Interval Training', 'Entrenamiento individual de hipertrofia intensa', 'Individual intense hypertrophy training', 'C'),
('FITNESS', 'FACIL', '¿Qué músculo es el principal implicado en el press militar (overhead press)?', 'Which muscle is primarily involved in the overhead press?', 'Dorsal ancho', 'Latissimus dorsi', 'Glúteos', 'Glutes', 'Gemelos', 'Calves', 'Deltoides', 'Deltoids', 'D'),
('FITNESS', 'FACIL', '¿Qué músculo trabaja principalmente el hip thrust?', 'Which muscle does the hip thrust primarily target?', 'Glúteos', 'Glutes', 'Abdominales', 'Abdominals', 'Trapecio', 'Trapezius', 'Antebrazos', 'Forearms', 'A'),
('FITNESS', 'MEDIA', '¿Qué son las agujetas (DOMS)?', 'What is DOMS (delayed onset muscle soreness)?', 'Una lesión muscular grave por sobrecarga', 'A severe overload muscle injury', 'El dolor muscular de aparición retardada tras un esfuerzo inusual', 'The delayed muscle pain that appears after unusual effort', 'La fatiga del sistema nervioso central', 'Central nervous system fatigue', 'La pérdida de fuerza permanente', 'Permanent strength loss', 'B'),
('FITNESS', 'MEDIA', '¿En qué consiste el principio de sobrecarga progresiva?', 'What does the principle of progressive overload consist of?', 'Entrenar siempre con el mismo peso para evitar lesiones', 'Always training with the same weight to avoid injury', 'Reducir el volumen de entrenamiento cada semana', 'Reducing training volume every week', 'Aumentar gradualmente la demanda impuesta al músculo para seguir progresando', 'Gradually increasing the demand placed on the muscle to keep progressing', 'Entrenar siempre hasta el fallo muscular', 'Always training to muscular failure', 'C'),
('FITNESS', 'MEDIA', 'En un curl de bíceps, ¿qué fase corresponde a la contracción excéntrica?', 'In a biceps curl, which phase corresponds to the eccentric contraction?', 'La fase de subida del peso', 'The lifting phase of the weight', 'El bloqueo isométrico en la parte alta', 'The isometric lock at the top', 'La contracción sin cambio de longitud muscular', 'Contraction without a change in muscle length', 'La bajada controlada del peso, donde el músculo se alarga bajo tensión', 'The controlled lowering, where the muscle lengthens under tension', 'D'),
('FITNESS', 'MEDIA', '¿Cuál de los siguientes es un ejercicio compuesto (multiarticular)?', 'Which of the following is a compound (multi-joint) exercise?', 'Sentadilla trasera con barra', 'Barbell back squat', 'Curl de bíceps con mancuerna', 'Dumbbell biceps curl', 'Extensión de tríceps en polea', 'Triceps pushdown', 'Elevaciones laterales', 'Lateral raises', 'A'),
('FITNESS', 'MEDIA', '¿En qué consiste una superserie (superset)?', 'What does a superset consist of?', 'Aumentar el peso en cada repetición', 'Increasing the weight on each repetition', 'Realizar dos ejercicios distintos seguidos, sin descanso entre ellos', 'Performing two different exercises back to back, without rest between them', 'Hacer solo una serie por ejercicio', 'Doing only one set per exercise', 'Descansar 5 minutos entre series', 'Resting 5 minutes between sets', 'B'),
('FITNESS', 'MEDIA', '¿En qué consiste una serie descendente (drop set)?', 'What does a drop set consist of?', 'Aumentar el peso al llegar al fallo', 'Increasing the weight upon reaching failure', 'Descansar 3 minutos entre cada repetición', 'Resting 3 minutes between each repetition', 'Reducir el peso inmediatamente al llegar al fallo y seguir repitiendo sin descanso', 'Reducing the weight immediately upon reaching failure and continuing without rest', 'Cambiar de ejercicio en cada repetición', 'Changing exercise on every repetition', 'C'),
('FITNESS', 'MEDIA', '¿Cuándo se recomienda generalmente el estiramiento estático?', 'When is static stretching generally recommended?', 'Antes de un esfuerzo explosivo, para activar el músculo', 'Before an explosive effort, to activate the muscle', 'Nunca, porque siempre reduce el rendimiento', 'Never, because it always reduces performance', 'Solo durante el calentamiento dinámico', 'Only during dynamic warm-up', 'Después del entrenamiento, cuando el músculo está caliente', 'After training, when the muscle is warm', 'D'),
('FITNESS', 'MEDIA', '¿Cuál es el objetivo principal del foam rolling (rodillo de espuma)?', 'What is the main purpose of foam rolling?', 'Liberación miofascial y reducción de la tensión muscular', 'Myofascial release and reduction of muscle tension', 'Aumentar directamente la fuerza máxima', 'Directly increasing maximum strength', 'Sustituir por completo el estiramiento estático', 'Completely replacing static stretching', 'Elevar el VO2 máx', 'Raising VO2 max', 'A'),
('FITNESS', 'MEDIA', '¿Qué mide la escala RPE (Esfuerzo Percibido)?', 'What does the RPE (Rate of Perceived Exertion) scale measure?', 'La frecuencia cardíaca máxima teórica', 'The theoretical maximum heart rate', 'El esfuerzo subjetivo percibido durante una serie', 'The subjective perceived effort during a set', 'El porcentaje exacto del 1RM medido con sensores', 'The exact percentage of 1RM measured by sensors', 'El volumen total de entrenamiento semanal', 'The total weekly training volume', 'B'),
('FITNESS', 'DIFICIL', '¿Qué caracteriza a las fibras musculares de contracción rápida (tipo II)?', 'What characterizes fast-twitch (Type II) muscle fibers?', 'Alta resistencia a la fatiga y baja producción de fuerza', 'High fatigue resistance and low force production', 'Uso predominante del metabolismo aeróbico', 'Predominant use of aerobic metabolism', 'Contracción rápida, mayor producción de fuerza y fatiga más rápida', 'Fast contraction, higher force output and quicker fatigue', 'Ser las únicas activas en ejercicios de baja intensidad', 'Being the only fibers active in low-intensity exercise', 'C'),
('FITNESS', 'DIFICIL', '¿Qué mide el VO2 máx?', 'What does VO2 max measure?', 'El número máximo de repeticiones antes del fallo', 'The maximum number of repetitions before failure', 'La frecuencia cardíaca en reposo', 'The resting heart rate', 'El porcentaje de grasa corporal saludable máximo', 'The maximum healthy body fat percentage', 'El volumen máximo de oxígeno que el cuerpo puede utilizar durante el ejercicio intenso', 'The maximum volume of oxygen the body can utilize during intense exercise', 'D'),
('FITNESS', 'DIFICIL', 'Según el principio del tamaño de Henneman, ¿en qué orden se reclutan las unidades motoras?', 'According to Henneman''s size principle, in what order are motor units recruited?', 'De las más pequeñas (resistentes a la fatiga) a las más grandes (de fuerza), según aumenta la demanda', 'From smallest (fatigue-resistant) to largest (high-force) as demand increases', 'De las más grandes a las más pequeñas', 'From largest to smallest', 'Al azar, sin ningún orden fisiológico', 'Randomly, with no physiological order', 'Solo se reclutan las de tipo II en cualquier esfuerzo', 'Only Type II units are recruited in any effort', 'A'),
('FITNESS', 'DIFICIL', '¿A qué se refiere la periodización del entrenamiento?', 'What does training periodization refer to?', 'Entrenar siempre con la misma intensidad y volumen todo el año', 'Always training with the same intensity and volume year-round', 'La organización planificada de las variables de entrenamiento en fases para optimizar el rendimiento', 'The planned organization of training variables into phases to optimize performance', 'Hacer únicamente ejercicios compuestos', 'Only performing compound exercises', 'Cambiar de gimnasio cada mes', 'Changing gyms every month', 'B'),
('FITNESS', 'DIFICIL', '¿Qué músculos forman el manguito rotador?', 'Which muscles make up the rotator cuff?', 'Deltoides, trapecio, dorsal ancho y romboides', 'Deltoid, trapezius, latissimus dorsi and rhomboids', 'Pectoral mayor, pectoral menor y serrato anterior', 'Pectoralis major, pectoralis minor and serratus anterior', 'Supraespinoso, infraespinoso, redondo menor y subescapular', 'Supraspinatus, infraspinatus, teres minor and subscapularis', 'Bíceps, tríceps, braquial y braquiorradial', 'Biceps, triceps, brachialis and brachioradialis', 'C'),
('FITNESS', 'DIFICIL', '¿Cuál es el objetivo principal de una semana de descarga (deload)?', 'What is the main purpose of a deload week?', 'Maximizar el peso levantado para batir récords personales', 'Maximizing the weight lifted to break personal records', 'Eliminar por completo el entrenamiento durante un mes', 'Completely eliminating training for a month', 'Duplicar el número de series', 'Doubling the number of sets', 'Reducir temporalmente el volumen o la intensidad para favorecer la recuperación y prevenir el sobreentrenamiento', 'Temporarily reducing volume or intensity to aid recovery and prevent overtraining', 'D'),
('FITNESS', 'DIFICIL', 'La maniobra de Valsalva, usada para estabilizar el core en levantamientos pesados, consiste en:', 'The Valsalva maneuver, used to brace the core during heavy lifts, involves:', 'Retener la respiración contra la glotis cerrada para aumentar la presión intraabdominal y estabilizar la columna', 'Holding the breath against a closed glottis to increase intra-abdominal pressure and stabilize the spine', 'Exhalar lentamente todo el aire antes de levantar el peso', 'Slowly exhaling all the air before lifting the weight', 'Respirar rápido y superficial durante todo el levantamiento', 'Breathing fast and shallow throughout the lift', 'Inhalar y exhalar al mismo tiempo que se levanta el peso', 'Inhaling and exhaling simultaneously while lifting', 'A'),
